/* A wrong entry size would make its_castore_flash_bytes lie, so it is checked wherever a
 * pointer is 32 bits. A host test with 64-bit pointers keeps the number of the device. */
#if UINTPTR_MAX == 0xFFFFFFFFu
_Static_assert(sizeof s_entries == (size_t)ITS_CASTORE_ENTRY_BYTES * ITS_CASTORE_COUNT,
               "its_castore_entry_t is not the size the generator counted with");
#endif

/* Certificate bytes, names and table together. All three are counted by the generator,
 * which is the only place that sees the names before the linker folds them. */
size_t its_castore_flash_bytes(void)
{
    return (size_t)ITS_CASTORE_CERT_BYTES + (size_t)ITS_CASTORE_NAME_BYTES
           + (size_t)ITS_CASTORE_ENTRY_BYTES * (size_t)ITS_CASTORE_COUNT;
}

/* Copy the entry at `index` of the table. */
bool its_castore_at(size_t index, its_castore_entry_t *out)
{
    if (index >= ITS_CASTORE_COUNT)
        return false;
    if (out)
        *out = s_entries[index];
    return true;
}

/* A walk beats a second sorted index here: the table is read only when a signer names an
 * authority the certificate cache does not hold, and a walk of a few hundred 8-byte
 * compares is some thousand instructions against the hundreds of thousands the signature
 * check behind it needs. An unknown hash_alg matches nothing on purpose. */
const its_castore_entry_t *its_castore_find(const uint8_t id8[8], uint8_t hash_alg)
{
    if (!id8)
        return NULL;
    bool sha384;
    if (hash_alg == ITS_TRUST_HASH_SHA384)
        sha384 = true;
    else if (hash_alg == ITS_TRUST_HASH_SHA256)
        sha384 = false;
    else
        return NULL;
    for (size_t i = 0; i < ITS_CASTORE_COUNT; i++)
    {
        const uint8_t *have = sha384 ? s_entries[i].id8_sha384 : s_entries[i].id8_sha256;
        if (memcmp(id8, have, 8) == 0)
            return &s_entries[i];
    }
    return NULL;
}

size_t its_castore_count(void)
{
    return ITS_CASTORE_COUNT;
}

uint32_t its_castore_fetched(void)
{
    return ITS_CASTORE_FETCHED;
}
